import numpy as np


def sigma0_linear(dn, lut):
    dn = np.asarray(dn, dtype=np.float64)
    lut = np.asarray(lut, dtype=np.float64)
    return (np.abs(dn) ** 2) / (lut ** 2)


def to_db(sigma0, eps=1e-10):
    s = np.asarray(sigma0, dtype=np.float64)
    return 10.0 * np.log10(np.maximum(s, eps))
